-- Supabase PostgreSQL Migration for Assessment Engine
-- Tables: questions (or assessment_questions) and assessment_results

CREATE TABLE IF NOT EXISTS assessment_questions (
    id TEXT PRIMARY KEY,
    category TEXT NOT NULL CHECK (category IN ('IQ', 'EQ', 'SQ', 'AQ')),
    question_type TEXT NOT NULL CHECK (question_type IN ('mcq', 'likert')),
    prompt_text TEXT NOT NULL,
    options JSONB,
    correct_answer TEXT,
    is_reverse BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS assessment_results (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    raw_scores JSONB NOT NULL,
    composite_score FLOAT NOT NULL,
    tier TEXT NOT NULL,
    ai_analysis JSONB NOT NULL,
    responses JSONB,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable Row Level Security
ALTER TABLE assessment_questions ENABLE ROW LEVEL SECURITY;
ALTER TABLE assessment_results ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY "Allow public read of assessment questions" ON assessment_questions FOR SELECT USING (true);
CREATE POLICY "Allow authenticated insert/read on assessment results" ON assessment_results FOR ALL USING (true);

-- 80 Question Inserts
clockwise. Final direction?', '["West", "East", "South-West", "North-West"]'::jsonb, 'West', false) ON CONFLICT (id) DO UPDATE SET prompt_text = EXCLUDED.prompt_text, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer;
